<script setup lang="ts">
import {ref,watch,nextTick,onBeforeUnmount} from 'vue'
import {moderateContent} from '@/api/wall'
import {ApiError} from '@/api/client'
import {errorMessage} from '@/api/identity'
import type {ModerationTarget,ModerationInput} from '@/wall/types'
const props=defineProps<{open:boolean;target:ModerationTarget|null}>(),emit=defineEmits<{close:[];saved:[]}>(),dialog=ref<HTMLDialogElement>(),text=ref(''),title=ref(''),reason=ref(''),internal=ref(''),error=ref(''),busy=ref(false),pending=ref<ModerationInput|null>(null)
let generation=0
const labels:Record<string,string>={EDIT:'管理员编辑',HIDE:'隐藏内容',RESTORE:'恢复展示',DELETE:'删除内容',KEEP:'处理举报并保留'}
watch(()=>`${props.open}:${props.target?.id}:${props.target?.action}`,async()=>{generation++;if(!props.open){dialog.value?.close();return}text.value=props.target?.text??'';title.value=props.target?.title??'';reason.value='';internal.value='';error.value='';pending.value=null;busy.value=false;await nextTick();dialog.value?.showModal()})
onBeforeUnmount(()=>generation++)
async function submit(){if(!props.target||busy.value)return;const g=generation;error.value='';if(!reason.value.trim()){error.value='请填写告知作者的原因。';return}if(props.target.action==='DELETE'&&!pending.value&&!confirm('确认删除这条内容？删除后不能恢复。'))return;busy.value=true;if(!pending.value)pending.value={requestId:crypto.randomUUID(),expectedVersion:props.target.version,action:props.target.action,text:text.value,title:title.value,authorReason:reason.value,internalNote:internal.value,reportIds:props.target.reportIds};try{await moderateContent(props.target.id,props.target.targetType,pending.value);if(g!==generation)return;pending.value=null;emit('saved')}catch(e){if(g===generation){error.value=errorMessage(e)+(e instanceof ApiError&&e.status===409?' 请保留当前输入，关闭后重新查看最新内容再处理。':'');if(e instanceof ApiError&&[400,401,403,404,409,429].includes(e.status))pending.value=null}}finally{if(g===generation)busy.value=false}}
</script>
<template><dialog ref="dialog" class="wall-dialog" aria-labelledby="wall-moderation-title" @cancel.prevent="!busy&&emit('close')"><form @submit.prevent="submit"><header class="wall-dialog-heading"><div><h2 id="wall-moderation-title">{{labels[target?.action??'']}}</h2><p class="muted">原因仅告知作者，内部备注只保存在管理记录。</p></div><button type="button" aria-label="关闭内容处理" :disabled="busy" @click="emit('close')">×</button></header><fieldset :disabled="busy||!!pending" class="wall-fieldset"><template v-if="target?.action==='EDIT'"><template v-if="target.kind==='ANNOUNCEMENT'"><label for="wall-edit-title">公告标题</label><input id="wall-edit-title" v-model="title" required></template><label for="wall-edit-text">留言内容</label><textarea id="wall-edit-text" v-model="text" required /></template><label for="wall-author-reason">告知作者的原因（必填）</label><textarea id="wall-author-reason" v-model="reason" required placeholder="说明具体问题，以及希望如何调整。"/><p class="muted">{{target?.action==='KEEP'?'仅记入管理记录；保留举报不发送负面提醒。':'将发到作者的铃铛消息，其他用户看不到。'}}</p><div class="wall-private-field"><label for="wall-internal-note">内部备注（选填，仅管理员可见）</label><textarea id="wall-internal-note" v-model="internal" placeholder="记录处理依据或后续关注事项"/></div><p class="muted">将处理 {{target?.reportIds.length??0}} 条已明确选择的举报，其余举报保留。</p></fieldset><p v-if="error" role="alert" class="wall-error">{{error}}</p><div class="wall-form-actions"><button type="button" :disabled="busy" @click="emit('close')">取消</button><button class="button-primary" :disabled="busy||Array.from(reason).length>200||Array.from(internal).length>500">{{busy?'正在处理…':pending?'确认上次处理结果':'确认处理并通知作者'}}</button></div></form></dialog></template>
